/**
 * Lightweight Standalone XLSX & CSV Parser/Generator for Offline Environments
 * Compatible with SheetJS XLSX API subsets:
 * XLSX.read, XLSX.utils.sheet_to_json, XLSX.utils.json_to_sheet, XLSX.utils.book_new, XLSX.utils.book_append_sheet, XLSX.writeFile
 */

(function (global) {
  const XLSX = {};

  // Simple CRC32 implementation for Zip packaging
  const CRC32_TABLE = (function() {
    let c, table = [];
    for (let n = 0; n < 256; n++) {
      c = n;
      for (let k = 0; k < 8; k++) {
        c = ((c & 1) ? (0xEDB88320 ^ (c >>> 1)) : (c >>> 1));
      }
      table[n] = c;
    }
    return table;
  })();

  function crc32(buf) {
    let crc = 0 ^ (-1);
    for (let i = 0; i < buf.length; i++) {
      crc = (crc >>> 8) ^ CRC32_TABLE[(crc ^ buf[i]) & 0xFF];
    }
    return (crc ^ (-1)) >>> 0;
  }

  // Mini Zip writer for generating valid XLSX packages
  class MiniZip {
    constructor() {
      this.files = [];
    }
    file(name, content) {
      let data = content;
      if (typeof content === 'string') {
        data = new TextEncoder().encode(content);
      }
      this.files.push({ name, data });
    }
    generate() {
      let fileRecords = [];
      let centralDir = [];
      let offset = 0;

      for (const f of this.files) {
        const nameBytes = new TextEncoder().encode(f.name);
        const crc = crc32(f.data);
        const size = f.data.length;

        // Local file header (30 bytes + name length)
        const header = new Uint8Array(30 + nameBytes.length);
        const view = new DataView(header.buffer);
        view.setUint32(0, 0x04034b50, true); // signature
        view.setUint16(4, 20, true);         // version needed
        view.setUint16(6, 0, true);          // flags
        view.setUint16(8, 0, true);          // compression: 0 = store
        view.setUint16(10, 0, true);         // mod time
        view.setUint16(12, 0, true);         // mod date
        view.setUint32(14, crc, true);       // crc32
        view.setUint32(18, size, true);      // compressed size
        view.setUint32(22, size, true);      // uncompressed size
        view.setUint16(26, nameBytes.length, true); // filename len
        view.setUint16(28, 0, true);         // extra len
        header.set(nameBytes, 30);

        fileRecords.push(header);
        fileRecords.push(f.data);

        // Central directory entry (46 bytes + name length)
        const cd = new Uint8Array(46 + nameBytes.length);
        const cdView = new DataView(cd.buffer);
        cdView.setUint32(0, 0x02014b50, true);
        cdView.setUint16(4, 20, true);
        cdView.setUint16(6, 20, true);
        cdView.setUint16(8, 0, true);
        cdView.setUint16(10, 0, true);
        cdView.setUint16(12, 0, true);
        cdView.setUint16(14, 0, true);
        cdView.setUint32(16, crc, true);
        cdView.setUint32(20, size, true);
        cdView.setUint32(24, size, true);
        cdView.setUint16(28, nameBytes.length, true);
        cdView.setUint16(30, 0, true);
        cdView.setUint16(32, 0, true);
        cdView.setUint16(34, 0, true);
        cdView.setUint16(36, 0, true);
        cdView.setUint32(38, 0, true);
        cdView.setUint32(42, offset, true);
        cd.set(nameBytes, 46);

        centralDir.push(cd);
        offset += header.length + size;
      }

      const cdOffset = offset;
      let cdSize = 0;
      centralDir.forEach(cd => cdSize += cd.length);

      // End of central directory record (22 bytes)
      const eocd = new Uint8Array(22);
      const eocdView = new DataView(eocd.buffer);
      eocdView.setUint32(0, 0x06054b50, true);
      eocdView.setUint16(4, 0, true);
      eocdView.setUint16(6, 0, true);
      eocdView.setUint16(8, this.files.length, true);
      eocdView.setUint16(10, this.files.length, true);
      eocdView.setUint32(12, cdSize, true);
      eocdView.setUint32(16, cdOffset, true);
      eocdView.setUint16(20, 0, true);

      // Combine all parts
      const totalLen = offset + cdSize + 22;
      const result = new Uint8Array(totalLen);
      let pos = 0;

      for (const rec of fileRecords) {
        result.set(rec, pos);
        pos += rec.length;
      }
      for (const cd of centralDir) {
        result.set(cd, pos);
        pos += cd.length;
      }
      result.set(eocd, pos);
      return result;
    }
  }

  // Mini Zip Reader
  function readZip(data) {
    const bytes = data instanceof Uint8Array ? data : new Uint8Array(data);
    const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
    const files = {};

    let pos = 0;
    while (pos < bytes.length - 4) {
      const sig = view.getUint32(pos, true);
      if (sig === 0x04034b50) { // Local file header
        const compMethod = view.getUint16(pos + 8, true);
        const compSize = view.getUint32(pos + 18, true);
        const uncompSize = view.getUint32(pos + 22, true);
        const nameLen = view.getUint16(pos + 26, true);
        const extraLen = view.getUint16(pos + 28, true);
        const nameBytes = bytes.slice(pos + 30, pos + 30 + nameLen);
        const name = new TextDecoder('utf-8').decode(nameBytes);
        const dataStart = pos + 30 + nameLen + extraLen;

        if (compMethod === 0) { // Stored
          const fileData = bytes.slice(dataStart, dataStart + uncompSize);
          files[name] = fileData;
        } else {
          // If compressed and DecompressionStream available (Chromium 80+)
          const compData = bytes.slice(dataStart, dataStart + compSize);
          files[name] = compData; // raw
        }
        pos = dataStart + compSize;
      } else {
        pos++;
      }
    }
    return files;
  }

  // Parse CSV
  function parseCSV(text) {
    const lines = text.split(/\r\n|\n|\r/);
    const result = [];
    for (const line of lines) {
      if (!line.trim()) continue;
      const row = [];
      let inQuotes = false;
      let curVal = '';
      for (let i = 0; i < line.length; i++) {
        const ch = line[i];
        if (ch === '"') {
          inQuotes = !inQuotes;
        } else if ((ch === ';' || ch === ',') && !inQuotes) {
          row.push(curVal.trim().replace(/^"|"$/g, ''));
          curVal = '';
        } else {
          curVal += ch;
        }
      }
      row.push(curVal.trim().replace(/^"|"$/g, ''));
      result.push(row);
    }
    return result;
  }

  // SheetJS API emulation
  XLSX.read = function (data, opts = {}) {
    if (typeof data === 'string') {
      const rows = parseCSV(data);
      const headers = rows[0] || [];
      const json = [];
      for (let i = 1; i < rows.length; i++) {
        const item = {};
        headers.forEach((h, idx) => {
          item[h] = rows[i][idx] || '';
        });
        json.push(item);
      }
      return {
        SheetNames: ['Sheet1'],
        Sheets: { Sheet1: { _json: json, _rows: rows } }
      };
    }

    // Binary array
    const bytes = new Uint8Array(data);
    // Check if it's text/csv in binary form
    try {
      const text = new TextDecoder('utf-8').decode(bytes.slice(0, 1000));
      if (text.includes(';') || (text.includes(',') && !text.startsWith('PK'))) {
        const fullText = new TextDecoder('utf-8').decode(bytes);
        return XLSX.read(fullText);
      }
    } catch (e) {}

    // ZIP / XLSX Parsing
    try {
      const zip = readZip(bytes);
      let sheetXml = '';
      let sharedStrings = [];

      // Shared strings
      if (zip['xl/sharedStrings.xml']) {
        const ssText = new TextDecoder('utf-8').decode(zip['xl/sharedStrings.xml']);
        const matches = ssText.match(/<t[^>]*>(.*?)<\/t>/g) || [];
        sharedStrings = matches.map(m => m.replace(/<\/?t[^>]*>/g, ''));
      }

      // Sheet 1
      if (zip['xl/worksheets/sheet1.xml']) {
        sheetXml = new TextDecoder('utf-8').decode(zip['xl/worksheets/sheet1.xml']);
      }

      const rows = [];
      const rowMatches = sheetXml.match(/<row[^>]*>(.*?)<\/row>/g) || [];

      for (const rXml of rowMatches) {
        const row = [];
        const cellMatches = rXml.match(/<c[^>]*>(.*?)<\/c>/g) || [];
        for (const cXml of cellMatches) {
          const isString = cXml.includes('t="s"');
          const vMatch = cXml.match(/<v>(.*?)<\/v>/);
          if (vMatch) {
            const val = vMatch[1];
            if (isString && sharedStrings[val] !== undefined) {
              row.push(sharedStrings[val]);
            } else {
              row.push(val);
            }
          } else {
            const tMatch = cXml.match(/<t[^>]*>(.*?)<\/t>/);
            row.push(tMatch ? tMatch[1] : '');
          }
        }
        if (row.length) rows.push(row);
      }

      const headers = rows[0] || [];
      const json = [];
      for (let i = 1; i < rows.length; i++) {
        const item = {};
        headers.forEach((h, idx) => {
          item[h] = rows[i][idx] || '';
        });
        json.push(item);
      }

      return {
        SheetNames: ['Sheet1'],
        Sheets: { Sheet1: { _json: json, _rows: rows } }
      };
    } catch (err) {
      throw new Error('Файл не является корректным документом Excel (.xlsx) или CSV.');
    }
  };

  XLSX.utils = {
    sheet_to_json: function (sheet) {
      return sheet._json || [];
    },
    json_to_sheet: function (data) {
      return { _json: data };
    },
    book_new: function () {
      return { SheetNames: [], Sheets: {} };
    },
    book_append_sheet: function (wb, sheet, name) {
      wb.SheetNames.push(name);
      wb.Sheets[name] = sheet;
    }
  };

  XLSX.writeFile = function (wb, filename) {
    const sheetName = wb.SheetNames[0] || 'Sheet1';
    const data = wb.Sheets[sheetName]?._json || [];
    if (!data.length) return;

    const headers = Object.keys(data[0]);
    
    // Construct XLSX OpenXML format via MiniZip
    const zip = new MiniZip();

    // 1. [Content_Types].xml
    zip.file('[Content_Types].xml', `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">
  <Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>
  <Default Extension="xml" ContentType="application/xml"/>
  <Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/>
  <Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>
</Types>`);

    // 2. _rels/.rels
    zip.file('_rels/.rels', `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">
  <Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/>
</Relationships>`);

    // 3. xl/_rels/workbook.xml.rels
    zip.file('xl/_rels/workbook.xml.rels', `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">
  <Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/>
</Relationships>`);

    // 4. xl/workbook.xml
    zip.file('xl/workbook.xml', `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships">
  <sheets>
    <sheet name="${sheetName}" sheetId="1" r:id="rId1"/>
  </sheets>
</workbook>`);

    // 5. xl/worksheets/sheet1.xml
    let sheetDataXml = '<sheetData>';
    
    // Header row
    sheetDataXml += '<row r="1">';
    headers.forEach((h, colIdx) => {
      const colLetter = String.fromCharCode(65 + (colIdx % 26));
      sheetDataXml += `<c r="${colLetter}1" t="inlineStr"><is><t>${escapeXml(h)}</t></is></c>`;
    });
    sheetDataXml += '</row>';

    // Data rows
    data.forEach((row, rowIdx) => {
      const rNum = rowIdx + 2;
      sheetDataXml += `<row r="${rNum}">`;
      headers.forEach((h, colIdx) => {
        const colLetter = String.fromCharCode(65 + (colIdx % 26));
        const val = row[h] !== undefined && row[h] !== null ? String(row[h]) : '';
        const isNum = !isNaN(Number(val)) && val.trim() !== '';
        if (isNum) {
          sheetDataXml += `<c r="${colLetter}${rNum}"><v>${val.trim()}</v></c>`;
        } else {
          sheetDataXml += `<c r="${colLetter}${rNum}" t="inlineStr"><is><t>${escapeXml(val)}</t></is></c>`;
        }
      });
      sheetDataXml += '</row>';
    });

    sheetDataXml += '</sheetData>';

    zip.file('xl/worksheets/sheet1.xml', `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main">
  ${sheetDataXml}
</worksheet>`);

    const zipBytes = zip.generate();
    const blob = new Blob([zipBytes], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = filename;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  function escapeXml(str) {
    return String(str || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
  }

  global.XLSX = XLSX;
})(window);
